    /**
     * Display the ConnectinSkillz candidate success stories page.
     */
    public function index(): View
    {
        $candidates = self::getCandidates();
        return view('pages.success-stories', compact('candidates'));
    }

    /**
     * Display a single candidate's dedicated testimonial page.
     */
    public function show(string $slug): View
    {
        $candidates = self::getCandidates();
        $search = strtolower(trim($slug));
        $currentIndex = null;

        foreach ($candidates as $index => $c) {
            if (
                strtolower($c['slug']) === $search ||
                strtolower($c['name']) === $search ||
                strtolower(str_replace('.', '-', $c['name'])) === $search ||
                strtolower(str_replace('-', '.', $search)) === strtolower($c['slug'])
            ) {
                $currentIndex = $index;
                break;
            }
        }

        if ($currentIndex === null) {
            abort(404);
        }

        $candidate = $candidates[$currentIndex];
        $total = count($candidates);
        $prevIndex = ($currentIndex - 1 + $total) % $total;
        $nextIndex = ($currentIndex + 1) % $total;
        $prevCandidate = $candidates[$prevIndex];
        $nextCandidate = $candidates[$nextIndex];

        return view('pages.story-detail', compact('candidate', 'prevCandidate', 'nextCandidate'));
    }
